"""Whole-day decomposition for model A by block of hours (notes 21.84): which input the error comes from, in both substitution orders."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
import market1 as M
SP = M.SP; P = np.load(f"{SP}/out/market1n_post.npz"); th = {k: float(np.median(P[k])) for k in M.PN}; Z = np.load(f"{SP}/out/shift15.npz"); Rh = pd.read_parquet(f"{SP}/out/market_hourly.parquet"); E = np.load(f"{SP}/out/eua_15min.npz")["eua"]; E = np.r_[E, np.full(max(0, len(Rh) * 4 - len(E)), np.nan)]; co2f = pd.Series(np.nanmean(E[: len(Rh) * 4].reshape(-1, 4), 1), index=Rh.index.tz_convert("UTC")).ffill()
BL = (("night 00-06", 0, 24), ("morning 06-10", 24, 40), ("midday 10-16", 40, 64), ("evening 16-22", 64, 88), ("late 22-24", 88, 96), ("whole day", 0, 96)); out = {}
for per, V in (("winter", "mid"), ("summer", "mid"), ("autumn", "v2")):
    I = np.load(f"{SP}/out/inputs_{per}.npz"); a = I["actual"].astype(float)[:, :96]; T = np.load(f"{SP}/out/tsshift_{V}_{per}.npz"); G = np.load(f"{SP}/out/gen_{V}_{per}.npz"); n = len(a); K = {k: np.zeros((n, 96)) for k in ("p0", "pL", "pU", "pLU", "pall", "du", "dl", "ut", "uh", "wind", "solar", "load")}
    for j, c in enumerate(I["cutoffs"]):
        d0 = int(I["cuts"][j]); t0 = pd.Timestamp(str(c)).tz_localize("UTC"); cj = float(co2f.asof(t0 - pd.Timedelta(hours=34))); Lj = 1.85 * float(I["gas"][j]) + 0.37 * cj; sl = slice(d0, d0 + 96); Lv, cv = np.full(96, Lj), np.full(96, cj); xh = T["xh"][j].astype(float)[:96]; nbh = T["nbh"][j].astype(float)[:96]; uh = T["median"][j].astype(float)[:96]; rlt = Z["rl"][sl]; dl = rlt - G["rl_pes"][j].astype(float)[:96]; x2 = rlt - Z["other"][sl]; nbt = Z["nbterm"][sl]; ut = x2 - Z["Sp"][sl] - nbt
        cl = lambda x, e: np.asarray(M.clear(th, x, Lv, cv, eps=e)) / 10; K["p0"][j] = cl(xh, uh + nbh); K["pL"][j] = cl(xh + dl, uh + nbh); K["pU"][j] = cl(xh, ut + nbh); K["pLU"][j] = cl(xh + dl, ut + nbh); K["pall"][j] = cl(x2, ut + nbt); K["du"][j] = uh - ut; K["dl"][j] = -dl; K["ut"][j] = ut; K["uh"][j] = uh
        for nm in ("wind", "solar", "load"): K[nm][j] = G[f"{nm}_pes"][j].astype(float)[:96] - G[f"{nm}_true"][j].astype(float)[:96]
    out[per] = (a, K); print(f"{per} ({n} days): check, clearing with all true inputs returns the price: mean abs difference {np.abs(K['pall'] - a).mean():.3f} ct")
    for lab, s0, s1 in BL:
        e = (K["p0"] - a)[:, s0:s1]; sg = np.sign(e); tot = np.abs(e).sum(); sh = lambda x: float((sg * x[:, s0:s1]).sum() / tot); m = lambda k: K[k][:, s0:s1]
        print(f"   {lab:14s} MAE {np.abs(e).mean():.2f} bias {e.mean():+.2f} | share from load {sh(K['p0'] - K['pL']):.2f} | {sh(K['pU'] - K['pLU']):.2f}; shift {sh(K['pL'] - K['pLU']):.2f} | {sh(K['p0'] - K['pU']):.2f}; rest {sh(K['pLU'] - a):.2f} || GW: load-forecast error mean {m('dl').mean():+.2f} abs {np.abs(m('dl')).mean():.2f} (wind {np.abs(m('wind')).mean():.2f}, solar {np.abs(m('solar')).mean():.2f}, load {np.abs(m('load')).mean():.2f}); shift error mean {m('du').mean():+.2f} abs {np.abs(m('du')).mean():.2f}; true shift sd {m('ut').std():.2f}, forecast shift sd {m('uh').std():.2f}")
    hi = a > np.quantile(a, 0.98); e = (K["p0"] - a); print(f"   top 2% of prices ({int(hi.sum())} slots): bias {e[hi].mean():+.2f}; of which load {(K['p0'] - K['pL'])[hi].mean():+.2f}, shift {(K['pL'] - K['pLU'])[hi].mean():+.2f}, rest {(K['pLU'] - a)[hi].mean():+.2f} | shift error GW {K['du'][hi].mean():+.2f}, true shift {K['ut'][hi].mean():+.2f}, forecast {K['uh'][hi].mean():+.2f}, load error {K['dl'][hi].mean():+.2f}")
np.savez_compressed(f"{SP}/out/day_decomp.npz", **{f"{p}_{k}": v.astype(np.float32) for p, (a, K) in out.items() for k, v in list(K.items()) + [("a", a)]})
